// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithBaseURL(router, si, "")
}

// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(baseURL+"/clients", wrapper.GetClients)
	router.POST(baseURL+"/clients", wrapper.PostClients)
	router.GET(baseURL+"/clients/:id", wrapper.GetClientsId)
	router.PUT(baseURL+"/clients/:id", wrapper.PutClientsId)
	router.GET(baseURL+"/clients/:id/events", wrapper.GetClientsIdEvents)
	router.GET(baseURL+"/clients/:id/services", wrapper.GetClientsIdServices)
	router.GET(baseURL+"/clients/:id/services/:service_id/events", wrapper.GetClientsIdServicesServiceIdEvents)
	router.GET(baseURL+"/events", wrapper.GetEvents)
	router.GET(baseURL+"/events/services/:id", wrapper.GetEventsServicesId)
	router.DELETE(baseURL+"/events/:id", wrapper.DeleteEventsId)
	router.GET(baseURL+"/events/:id", wrapper.GetEventsId)
	router.PUT(baseURL+"/events/:id", wrapper.PutEventsId)
	router.GET(baseURL+"/events/:id/participants", wrapper.GetEventsIdParticipants)
	router.PUT(baseURL+"/events/:id/participants", wrapper.PutEventsIdParticipants)
	router.GET(baseURL+"/events/:id/participants/report", wrapper.GetEventsIdParticipantsReport)
	router.DELETE(baseURL+"/events/:id/participants/:participant_id", wrapper.DeleteEventsIdParticipantsParticipantId)
	router.GET(baseURL+"/locations", wrapper.GetLocations)
	router.POST(baseURL+"/locations", wrapper.PostLocations)
	router.DELETE(baseURL+"/locations/:id", wrapper.DeleteLocationsId)
	router.GET(baseURL+"/locations/:id", wrapper.GetLocationsId)
	router.PUT(baseURL+"/locations/:id", wrapper.PutLocationsId)
	router.POST(baseURL+"/login", wrapper.PostLogin)
	router.GET(baseURL+"/services", wrapper.GetServices)
	router.GET(baseURL+"/services/:id", wrapper.GetServicesId)
	router.PUT(baseURL+"/services/:id", wrapper.PutServicesId)
	router.GET(baseURL+"/timeSlots", wrapper.GetTimeSlots)
	router.POST(baseURL+"/timeSlots", wrapper.PostTimeSlots)
	router.DELETE(baseURL+"/timeSlots/:id", wrapper.DeleteTimeSlotsId)
	router.GET(baseURL+"/timeSlots/:id", wrapper.GetTimeSlotsId)
	router.PUT(baseURL+"/timeSlots/:id", wrapper.PutTimeSlotsId)
	router.PATCH(baseURL+"/timeSlots/:id/activate", wrapper.PatchTimeSlotsIdActivate)
	router.PATCH(baseURL+"/timeSlots/:id/archive", wrapper.PatchTimeSlotsIdArchive)
	router.POST(baseURL+"/volunteers", wrapper.PostVolunteers)
	router.GET(baseURL+"/volunteers/:tg_id", wrapper.GetVolunteersTgId)
	router.PUT(baseURL+"/volunteers/:tg_id", wrapper.PutVolunteersTgId)

}

